mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { decide } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g2-2/bot.mjs';

const base = { userId: 'u1', category: 'marketing', timezone: 'Europe/Istanbul', quietStart: '22:00', quietEnd: '07:30' };
const at = (iso) => new Date(iso);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log('ok -', name); };

ok('transactional bypasses quiet hours and cap', () => {
  const t = { ...base, category: 'transactional', userId: 'tx' };
  const when = at('2026-10-23T22:00:00Z'); // 01:00 Istanbul, inside quiet window
  for (let i = 0; i < 10; i++) assert.deepEqual(decide(t, when), { send: true, rule: null });
});

ok('marketing inside wrap-around quiet window is blocked with quiet-hours', () => {
  const u = { ...base, userId: 'q1' };
  assert.deepEqual(decide(u, at('2026-10-23T20:00:00Z')), { send: false, rule: 'quiet-hours' }); // 23:00 local
  assert.deepEqual(decide(u, at('2026-10-23T03:59:00Z')), { send: false, rule: 'quiet-hours' }); // 06:59 local
  assert.deepEqual(decide(u, at('2026-10-23T04:30:00Z')), { send: true, rule: null });          // 07:30 local (end exclusive)
  assert.deepEqual(decide(u, at('2026-10-23T19:00:00Z')), { send: true, rule: null });          // 22:00 local (start inclusive -> blocked!)
});
EOF
echo written

cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { decide } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g2-2/bot.mjs';

const IST = { userId: 'u1', category: 'marketing', timezone: 'Europe/Istanbul', quietStart: '22:00', quietEnd: '07:30' };
const at = (iso) => new Date(iso);
const SEND = { send: true, rule: null };
const block = (rule) => ({ send: false, rule });
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log('ok -', name); };

ok('transactional bypasses quiet hours and cap', () => {
  const t = { ...IST, category: 'transactional', userId: 'tx' };
  for (let i = 0; i < 10; i++) assert.deepEqual(decide(t, at('2026-10-23T19:30:00Z')), SEND); // 22:30 local
});

ok('wrap-around quiet window boundaries (Istanbul = UTC+3)', () => {
  const u = { ...IST, userId: 'q1' };
  assert.deepEqual(decide(u, at('2026-10-23T19:00:00Z')), block('quiet-hours')); // 22:00 local, start inclusive
  assert.deepEqual(decide(u, at('2026-10-23T20:00:00Z')), block('quiet-hours')); // 23:00 local
  assert.deepEqual(decide(u, at('2026-10-23T03:59:00Z')), block('quiet-hours')); // 06:59 local
  assert.deepEqual(decide(u, at('2026-10-23T04:30:00Z')), SEND);                 // 07:30 local, end exclusive
  assert.deepEqual(decide(u, at('2026-10-23T12:00:00Z')), SEND);                 // 15:00 local
});

ok('quiet-blocked marketing does not consume the daily cap', () => {
  const u = { ...IST, userId: 'q2' };
  assert.deepEqual(decide(u, at('2026-10-23T20:00:00Z')), block('quiet-hours'));
  assert.deepEqual(decide(u, at('2026-10-23T20:00:00Z')), block('quiet-hours'));
  for (let i = 0; i < 3; i++) assert.deepEqual(decide(u, at('2026-10-23T12:00:00Z')), SEND);
  assert.deepEqual(decide(u, at('2026-10-23T12:00:00Z')), block('daily-cap'));
});

ok('daily cap: 3 marketing sends per local day, 4th blocked', () => {
  const u = { ...IST, userId: 'c1' };
  const noon = at('2026-10-23T09:00:00Z'); // 12:00 local
  assert.deepEqual(decide(u, noon), SEND);
  assert.deepEqual(decide(u, noon), SEND);
  assert.deepEqual(decide(u, noon), SEND);
  assert.deepEqual(decide(u, noon), block('daily-cap'));
  assert.deepEqual(decide(u, noon), block('daily-cap'));
});

ok('cap resets at the customer local midnight, not UTC midnight', () => {
  const u = { ...IST, userId: 'c2', quietStart: '00:00', quietEnd: '00:00' }; // empty window
  // 2026-10-23 21:30 UTC = 2026-10-24 00:30 Istanbul -> new local day already
  for (let i = 0; i < 3; i++) assert.deepEqual(decide(u, at('2026-10-23T20:00:00Z')), SEND); // 23:00 local Oct 23
  assert.deepEqual(decide(u, at('2026-10-23T20:30:00Z')), block('daily-cap'));                // 23:30 local Oct 23
  assert.deepEqual(decide(u, at('2026-10-23T21:30:00Z')), SEND);                              // 00:30 local Oct 24
});

ok('same instant, different customer zones -> different local days', () => {
  const instant = at('2026-10-23T22:30:00Z');
  const la = { userId: 'la', category: 'marketing', timezone: 'America/Los_Angeles', quietStart: '00:00', quietEnd: '00:00' }; // Oct 23 15:30
  const ist = { ...la, userId: 'ist', timezone: 'Europe/Istanbul' };                                                           // Oct 24 01:30
  for (let i = 0; i < 3; i++) decide(la, instant);
  assert.deepEqual(decide(la, instant), block('daily-cap'));
  assert.deepEqual(decide(ist, instant), SEND);
});

ok('DST fall-back day (America/New_York, 2026-11-01) counts as one local day', () => {
  const u = { userId: 'dst', category: 'marketing', timezone: 'America/New_York', quietStart: '00:00', quietEnd: '00:00' };
  assert.deepEqual(decide(u, at('2026-11-01T05:30:00Z')), SEND); // 01:30 EST? (local Oct 31 is 01:30 EDT) -> still Oct 31 local
  assert.deepEqual(decide(u, at('2026-11-01T06:30:00Z')), SEND); // 01:30 EST Nov 1
  assert.deepEqual(decide(u, at('2026-11-01T07:30:00Z')), SEND); // 02:30 EST Nov 1
  assert.deepEqual(decide(u, at('2026-11-01T12:00:00Z')), block('daily-cap'));
});

ok('empty window (start === end) blocks nothing', () => {
  const u = { ...IST, userId: 'e1', quietStart: '08:00', quietEnd: '08:00' };
  assert.deepEqual(decide(u, at('2026-10-23T05:00:00Z')), SEND); // 08:00 local
});

ok('non-wrapping window', () => {
  const u = { ...IST, userId: 'nw', quietStart: '13:00', quietEnd: '14:00' };
  assert.deepEqual(decide(u, at('2026-10-23T10:30:00Z')), block('quiet-hours')); // 13:30 local
  assert.deepEqual(decide(u, at('2026-10-23T11:00:00Z')), SEND);                 // 14:00 local
});

ok('users have independent caps', () => {
  const a = { ...IST, userId: 'ia', quietStart: '00:00', quietEnd: '00:00' };
  const b = { ...a, userId: 'ib' };
  const t = at('2026-10-23T09:00:00Z');
  for (let i = 0; i < 3; i++) decide(a, t);
  assert.deepEqual(decide(a, t), block('daily-cap'));
  assert.deepEqual(decide(b, t), SEND);
});

ok('invalid input throws instead of sending', () => {
  const t = at('2026-10-23T09:00:00Z');
  assert.throws(() => decide({ ...IST, timezone: 'Mars/Olympus' }, t), RangeError);
  assert.throws(() => decide({ ...IST, quietStart: '24:00' }, t), TypeError);
  assert.throws(() => decide({ ...IST, quietEnd: '7:30' }, t), TypeError);
  assert.throws(() => decide({ ...IST, category: 'promo' }, t), TypeError);
  assert.throws(() => decide({ ...IST, userId: '' }, t), TypeError);
  assert.throws(() => decide(IST, '2026-10-23'), TypeError);
  assert.throws(() => decide(IST, new Date('nope')), TypeError);
});

console.log(`\n${n} checks passed`);
EOF
cd /tmp/bot-check && node check.mjs
